import{_ as p,a0 as g,w as h,s as r,I as s,x as a,a1 as t,A as l,ao as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"用 PGP 保護代碼完整性（六）：在 Git 上使用 PGP | LCTT x X-CMD","titleTemplate":false,"description":"用 PGP 保護代碼完整性（六）：在 Git 上使用 PGP | LCTT (201901) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 PGP 保護代碼完整性（六）：在 Git 上使用 PGP | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 PGP 保護代碼完整性（六）：在 Git 上使用 PGP | LCTT (201901) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201901/20180321 Protecting Code Integrity with PGP - Part 6- Using PGP with Git","title":"用 PGP 保護代碼完整性（六）：在 Git 上使用 PGP","tag":"201901","desc":""},"relativePath":"201901/20180321 Protecting Code Integrity with PGP - Part 6- Using PGP with Git.md","filePath":"[post].md"}'),d={name:"201901/20180321 Protecting Code Integrity with PGP - Part 6- Using PGP with Git.md"};function o(c,i,k,b,u,f){const e=g("Link");return h(),r("div",null,[i[24]||(i[24]=s("h1",{id:"用-pgp-保護代碼完整性-六-在-git-上使用-pgp",tabindex:"-1"},[a("用 PGP 保護代碼完整性（六）：在 Git 上使用 PGP "),s("a",{class:"header-anchor",href:"#用-pgp-保護代碼完整性-六-在-git-上使用-pgp","aria-label":"Permalink to “用 PGP 保護代碼完整性（六）：在 Git 上使用 PGP”"},"​")],-1)),i[25]||(i[25]=s("blockquote",null,[s("p",null,"我們繼續我們的 PGP 實踐系列，來看看簽名標籤的標籤和提交，這可以幫你確保你的倉庫沒有被篡改。")],-1)),i[26]||(i[26]=s("p",null,[s("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/global-network.jpg?itok=h_hhZc36",alt:""})],-1)),i[27]||(i[27]=s("p",null,"在本系列教程中，我們提供了一個使用 PGP 的實用指南，包括基本概念和工具、生成和保護你的密鑰。如果你錯過了前面的文章，你可以查看下面的鏈接。在這篇文章中，我們談一談在 Git 中如何集成 PGP、使用簽名的標籤，然後介紹簽名提交，最後添加簽名推送的支持。",-1)),s("ul",null,[s("li",null,[t(e,{href:"https://linux.cn/article-9524-1.html"},{default:l(()=>[...i[0]||(i[0]=[a("第一部分：基本概念和工具",-1)])]),_:1})]),s("li",null,[t(e,{href:"https://linux.cn/article-9529-1.html"},{default:l(()=>[...i[1]||(i[1]=[a("第二部分：生成你的主密鑰",-1)])]),_:1})]),s("li",null,[t(e,{href:"https://linux.cn/article-9607-1.html"},{default:l(()=>[...i[2]||(i[2]=[a("第三部分：生成 PGP 子密鑰",-1)])]),_:1})]),s("li",null,[t(e,{href:"https://linux.cn/article-10402-1.html"},{default:l(()=>[...i[3]||(i[3]=[a("第四部分：將主密鑰移到離線存儲中",-1)])]),_:1})]),s("li",null,[t(e,{href:"https://linux.cn/article-10415-1.html"},{default:l(()=>[...i[4]||(i[4]=[a("第五部分：將子密鑰移到硬件設備中",-1)])]),_:1})])]),i[28]||(i[28]=s("p",null,"Git 的核心特性之一就是它的去中心化本質 —— 一旦倉庫克隆到你的本地系統，你就擁有了項目的完整歷史，包括所有的標籤、提交和分支。然而由於存在着成百上千的克隆倉庫，如何才能驗證你下載的倉庫沒有被惡意的第三方做過篡改？你可以從 GitHub 或一些貌似官方的位置來克隆它們，但是如果有些人故意欺騙了你怎麼辦？",-1)),s("p",null,[i[6]||(i[6]=a("或者在你參與的一些項目上發現了後門，而 “Author” 行顯示是你乾的，然而你很確定 ",-1)),t(e,{href:"https://github.com/jayphelps/git-blame-someone-else"},{default:l(()=>[...i[5]||(i[5]=[a("不是你乾的",-1)])]),_:1}),i[7]||(i[7]=a("，會發生什麼情況？",-1))]),i[29]||(i[29]=n(`<p>為解決上述問題，Git 添加了 PGP 集成。簽名的標籤通過確認它的內容與創建這個標籤的開發者的工作站上的內容完全一致來證明倉庫的完整性，而簽名的提交幾乎是不可能在不訪問你的 PGP 密鑰的情況下能夠假冒你。</p><h4 id="清單" tabindex="-1">清單 <a class="header-anchor" href="#清單" aria-label="Permalink to “清單”">​</a></h4><ul><li>瞭解簽名的標籤、提交和推送（必要）</li><li>配置 git 使用你的密鑰（必要）</li><li>學習標籤如何簽名和驗證（必要）</li><li>配置 git 總是簽名帶註釋標籤（推薦）</li><li>學習提交如何簽名和驗證工作（必要）</li><li>配置 git 總是簽名提交（推薦）</li><li>配置 gpg-agent 選項（必要）</li></ul><h4 id="考慮事項" tabindex="-1">考慮事項 <a class="header-anchor" href="#考慮事項" aria-label="Permalink to “考慮事項”">​</a></h4><p>git 實現了 PGP 的多級集成，首先從簽名標籤開始，接着介紹簽名提交，最後添加簽名推送的支持。</p><h5 id="瞭解-git-哈希" tabindex="-1">瞭解 Git 哈希 <a class="header-anchor" href="#瞭解-git-哈希" aria-label="Permalink to “瞭解 Git 哈希”">​</a></h5><p>git 是一個複雜的東西，為了你能夠更好地掌握它如何集成 PGP，你需要了解什麼是”哈希“。我們將它歸納為兩種類型的哈希：樹哈希和提交哈希。</p><h6 id="樹哈希" tabindex="-1">樹哈希 <a class="header-anchor" href="#樹哈希" aria-label="Permalink to “樹哈希”">​</a></h6><p>每次你向倉庫提交一個變更，對於倉庫中的每個子目錄，git 都會記錄它裏面所有對象的校驗和哈希 —— 內容（blobs）、目錄（trees）、文件名和許可等等。它只對每次提交中發生變更的樹和內容做此操作，這樣在只變更樹的一小部分時就不必去重新計算整個樹的校驗和。</p><p>然後再計算和存儲處於頂級的樹的校驗和，這樣如果倉庫的任何一部分發生變化，校驗和將不可避免地發生變化。</p><h6 id="提交哈希" tabindex="-1">提交哈希 <a class="header-anchor" href="#提交哈希" aria-label="Permalink to “提交哈希”">​</a></h6><p>一旦創建了樹哈希，git 將計算提交哈希，它將包含有關倉庫和變更的下列信息：</p><ul><li>樹哈希的校驗和</li><li>變更前樹哈希的校驗和（父級）</li><li>有關作者的信息（名字、email、創作時間）</li><li>有關提交者的信息（名字、email、提交時間）</li><li>提交信息</li></ul><h6 id="哈希函數" tabindex="-1">哈希函數 <a class="header-anchor" href="#哈希函數" aria-label="Permalink to “哈希函數”">​</a></h6><p>在寫這篇文章時，雖然研究一種更強大的、抗碰撞的算法的工作正在進行，但 git 仍然使用的是 SHA1 哈希機制去計算校驗和。注意，git 已經包含了碰撞防範程序，因此認為對 git 成功進行碰撞攻擊仍然是不可行的。</p><h4 id="帶註釋標籤和標籤簽名" tabindex="-1">帶註釋標籤和標籤簽名 <a class="header-anchor" href="#帶註釋標籤和標籤簽名" aria-label="Permalink to “帶註釋標籤和標籤簽名”">​</a></h4><p>在每個 Git 倉庫中，標籤允許開發者標記特定的提交。標籤可以是 “輕量級的” —— 幾乎只是一個特定提交上的指針，或者它們可以是 “帶註釋的”，它自己將成為 git 樹中的項目。一個帶註釋標籤對象包含所有下列的信息：</p><ul><li>成為標籤的提交的哈希的校驗和</li><li>標籤名字</li><li>關於打標籤的人的信息（名字、email、打標籤時間）</li><li>標籤信息</li></ul><p>一個 PGP 簽名的標籤是一個帶有將所有這些條目封裝進一個 PGP 簽名的帶註釋標籤。當開發者簽名他們的 git 標籤時，他們實際上是向你保證瞭如下的信息：</p><ul><li>他們是誰（以及他們為什麼應該被信任）</li><li>他們在簽名時的倉庫狀態是什麼樣： <ul><li>標籤包含的提交的哈希 <ul><li>提交的哈希包含了頂級樹的哈希 <ul><li>頂級樹哈希包含了所有文件、內容和子樹的哈希</li></ul></li><li>它也包含有關作者的所有信息</li><li>包含變更發生時的精確時間</li></ul></li></ul></li></ul><p>當你克隆一個倉庫並驗證一個簽名的標籤時，就是向你以密碼方式保證：倉庫中的所有內容、包括所有它的歷史，與開發者簽名時在它的計算機上的倉庫完全一致。</p><h4 id="簽名的提交" tabindex="-1">簽名的提交 <a class="header-anchor" href="#簽名的提交" aria-label="Permalink to “簽名的提交”">​</a></h4><p>簽名的提交與簽名的標籤非常類似 —— PGP 簽名的是提交對象的內容，而不是標籤對象的內容。一個提交簽名也給你提供了開發者簽名時開發者樹上的全部可驗證信息。標籤簽名和提交的 PGP 簽名提供了有關倉庫和它的完整歷史的完全一致的安全保證。</p><h4 id="簽名的推送" tabindex="-1">簽名的推送 <a class="header-anchor" href="#簽名的推送" aria-label="Permalink to “簽名的推送”">​</a></h4><p>為了完整起見，在這裏包含了簽名的推送這一功能，因為在你使用這個功能之前，需要在接收推送的服務器上先啓用它。正如我們在上面所説過的，PGP 簽名一個 git 對象就是提供了開發者的 git 樹當時的可驗證信息，但不提供開發者對那個樹意圖相關的信息。</p><p>比如，你可以在你自己復刻的 git 倉庫的一個實驗分支上嘗試一個很酷的特性，為了評估它，你提交了你的工作，但是有人在你的代碼中發現了一個惡意的 bug。由於你的提交是經過正確簽名的，因此有人可能將包含有惡意 bug 的分支推入到 master 分支中，從而在生產系統中引入一個漏洞。由於提交是經過你的密鑰正確簽名的，所以一切看起來都是合理合法的，而當 bug 被發現時，你的聲譽就會因此而受到影響。</p><p>在 <code>git push</code> 時，為了驗證提交的意圖而不僅僅是驗證它的內容，添加了要求 PGP 推送簽名的功能。</p><h4 id="配置-git-使用你的-pgp-密鑰" tabindex="-1">配置 git 使用你的 PGP 密鑰 <a class="header-anchor" href="#配置-git-使用你的-pgp-密鑰" aria-label="Permalink to “配置 git 使用你的 PGP 密鑰”">​</a></h4><p>如果在你的鑰匙環上只有一個密鑰，那麼你就不需要再做額外的事了，因為它是你的默認密鑰。</p><p>然而，如果你有多個密鑰，那麼你必須要告訴 git 去使用哪一個密鑰。（<code>[fpr]</code> 是你的密鑰的指紋）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git config --global user.signingKey [fpr]</span></span></code></pre></div><p>注意：如果你有一個不同的 <code>gpg2</code> 命令，那麼你應該告訴 git 總是去使用它，而不是傳統的版本 1 的 <code>gpg</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git config --global gpg.program gpg2</span></span></code></pre></div><h4 id="如何使用簽名標籤" tabindex="-1">如何使用簽名標籤 <a class="header-anchor" href="#如何使用簽名標籤" aria-label="Permalink to “如何使用簽名標籤”">​</a></h4><p>創建一個簽名的標籤，只要傳遞一個簡單地 <code>-s</code> 開關給 <code>tag</code> 命令即可：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git tag -s [tagname]</span></span></code></pre></div><p>我們建議始終對 git 標籤簽名，這樣讓其它的開發者確信他們使用的 git 倉庫沒有被惡意地修改過（比如，引入後門）：</p><h5 id="如何驗證簽名的標籤" tabindex="-1">如何驗證簽名的標籤 <a class="header-anchor" href="#如何驗證簽名的標籤" aria-label="Permalink to “如何驗證簽名的標籤”">​</a></h5><p>驗證一個簽名的標籤，只需要簡單地使用 <code>verify-tag</code> 命令即可：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git verify-tag [tagname]</span></span></code></pre></div><p>如果你要驗證其他人的 git 標籤，那麼就需要你導入他的 PGP 公鑰。請參考 “可信任的團隊溝通” 一文中關於此主題的指導。</p><h5 id="在拉取時驗證" tabindex="-1">在拉取時驗證 <a class="header-anchor" href="#在拉取時驗證" aria-label="Permalink to “在拉取時驗證”">​</a></h5><p>如果你從項目倉庫的其它復刻中拉取一個標籤，git 將自動驗證簽名，並在合併操作時顯示結果：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git pull [url] tags/sometag</span></span></code></pre></div><p>合併信息將包含類似下面的內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Merge tag &#39;sometag&#39; of [url]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Tag message]</span></span>
<span class="line"><span></span></span>
<span class="line"><span># gpg: Signature made [...]</span></span>
<span class="line"><span># gpg: Good signature from [...]</span></span></code></pre></div><h4 id="配置-git-始終簽名帶註釋標籤" tabindex="-1">配置 git 始終簽名帶註釋標籤 <a class="header-anchor" href="#配置-git-始終簽名帶註釋標籤" aria-label="Permalink to “配置 git 始終簽名帶註釋標籤”">​</a></h4><p>很可能的是，你正在創建一個帶註釋標籤，你應該去簽名它。強制 git 始終簽名帶註釋的標籤，你可以設置一個全局配置選項：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git config --global tag.forceSignAnnotated true</span></span></code></pre></div><p>或者，你始終記得每次都傳遞一個 <code>-s</code> 開關：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git tag -asm &quot;Tag message&quot; tagname</span></span></code></pre></div><h4 id="如何使用簽名的提交" tabindex="-1">如何使用簽名的提交 <a class="header-anchor" href="#如何使用簽名的提交" aria-label="Permalink to “如何使用簽名的提交”">​</a></h4><p>創建一個簽名的提交很容易，但是將它納入到你的工作流中卻很困難。許多項目使用簽名的提交作為一種 “Committed-by:” 的等價行，它記錄了代碼來源 —— 除了跟蹤項目歷史外，簽名很少有人去驗證。在某種意義上，簽名的提交用於 “篡改證據”，而不是 git 工作流的 “篡改證明”。</p><p>為創建一個簽名的提交，你只需要 <code>git commit</code> 命令傳遞一個 <code>-S</code> 標誌即可（由於它與另一個標誌衝突，所以改為大寫的 <code>-S</code>）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git commit -S</span></span></code></pre></div><p>我們建議始終使用簽名提交，並要求項目所有成員都這樣做，這樣其它人就可以驗證它們（下面就講到如何驗證）。</p><h5 id="如何去驗證簽名的提交" tabindex="-1">如何去驗證簽名的提交 <a class="header-anchor" href="#如何去驗證簽名的提交" aria-label="Permalink to “如何去驗證簽名的提交”">​</a></h5><p>驗證簽名的提交需要使用 <code>verify-commit</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git verify-commit [hash]</span></span></code></pre></div><p>你也可以查看倉庫日誌，要求所有提交簽名是被驗證和顯示的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git log --pretty=short --show-signature</span></span></code></pre></div><h5 id="在-git-合併時驗證提交" tabindex="-1">在 git 合併時驗證提交 <a class="header-anchor" href="#在-git-合併時驗證提交" aria-label="Permalink to “在 git 合併時驗證提交”">​</a></h5><p>如果項目的所有成員都簽名了他們的提交，你可以在合併時強制進行簽名檢查（然後使用 <code>-S</code> 標誌對合並操作本身進行簽名）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git merge --verify-signatures -S merged-branch</span></span></code></pre></div><p>注意，如果有一個提交沒有簽名或驗證失敗，將導致合併操作失敗。通常情況下，技術是最容易的部分 —— 而人的因素使得項目中很難採用嚴格的提交驗證。</p><h5 id="如果你的項目在補丁管理上採用郵件列表" tabindex="-1">如果你的項目在補丁管理上採用郵件列表 <a class="header-anchor" href="#如果你的項目在補丁管理上採用郵件列表" aria-label="Permalink to “如果你的項目在補丁管理上採用郵件列表”">​</a></h5><p>如果你的項目在提交和處理補丁時使用一個郵件列表，那麼一般很少使用簽名提交，因為通過那種方式發送時，簽名信息將會丟失。對提交進行簽名仍然是非常有用的，這樣其他人就能引用你託管在公開 git 樹作為參考，但是上游項目接收你的補丁時，仍然不能直接使用 git 去驗證它們。</p><p>儘管，你仍然可以簽名包含補丁的電子郵件。</p><h4 id="配置-git-始終簽名提交" tabindex="-1">配置 git 始終簽名提交 <a class="header-anchor" href="#配置-git-始終簽名提交" aria-label="Permalink to “配置 git 始終簽名提交”">​</a></h4><p>你可以告訴 git 總是簽名提交：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git config --global commit.gpgSign true</span></span></code></pre></div><p>或者你每次都記得給 <code>git commit</code> 操作傳遞一個 <code>-S</code> 標誌（包括 <code>—amend</code>）。</p><h4 id="配置-gpg-agent-選項" tabindex="-1">配置 gpg-agent 選項 <a class="header-anchor" href="#配置-gpg-agent-選項" aria-label="Permalink to “配置 gpg-agent 選項”">​</a></h4><p>GnuPG agent 是一個守護工具，它能在你使用 gpg 命令時隨時自動啓動，並運行在後台來緩存私鑰的密碼。這種方式讓你只需要解鎖一次密鑰就可以重複地使用它（如果你需要在一個自動腳本中籤署一組 git 操作，而不想重複輸入密鑰，這種方式就很方便）。</p><p>為了調整緩存中的密鑰過期時間，你應該知道這兩個選項：</p><ul><li><code>default-cache-ttl</code>（秒）：如果在 TTL 過期之前再次使用同一個密鑰，這個倒計時將重置成另一個倒計時週期。缺省值是 600（10 分鐘）。</li><li><code>max-cache-ttl</code>（秒）：自首次密鑰輸入以後，不論最近一次使用密鑰是什麼時間，只要最大值的 TTL 倒計時過期，你將被要求再次輸入密碼。它的缺省值是 30 分鐘。</li></ul><p>如果你認為這些缺省值過短（或過長），你可以編輯 <code>~/.gnupg/gpg-agent.conf</code> 文件去設置你自己的值：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># set to 30 minutes for regular ttl, and 2 hours for max ttl</span></span>
<span class="line"><span>default-cache-ttl 1800</span></span>
<span class="line"><span>max-cache-ttl 7200</span></span></code></pre></div><h5 id="補充-與-ssh-一起使用-gpg-agent" tabindex="-1">補充：與 ssh 一起使用 gpg-agent <a class="header-anchor" href="#補充-與-ssh-一起使用-gpg-agent" aria-label="Permalink to “補充：與 ssh 一起使用 gpg-agent”">​</a></h5>`,79)),s("p",null,[i[9]||(i[9]=a("如果你創建了一個 ",-1)),t(e,{href:"https://www.linux.com/users/mricon"},{default:l(()=>[...i[8]||(i[8]=[a("A",-1)])]),_:1}),i[10]||(i[10]=a("（驗證）密鑰，並將它移到了智能卡，你可以將它用到 ssh 上，為你的 ssh 會話添加一個雙因子驗證。為了與 agent 溝通你只需要告訴你的環境去使用正確的套接字文件即可。",-1))]),i[30]||(i[30]=n(`<p>首先，添加下列行到你的 <code>~/.gnupg/gpg-agent.conf</code> 文件中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>enable-ssh-support</span></span></code></pre></div><p>接着，添加下列行到你的 <code>.bashrc</code> 文件中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>export SSH_AUTH_SOCK=$(gpgconf --list-dirs agent-ssh-socket)</span></span></code></pre></div><p>為了讓改變生效，你需要殺掉正在運行的 gpg-agent 進程，並重新啓動一個新的登入會話：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ killall gpg-agent</span></span>
<span class="line"><span>$ bash</span></span>
<span class="line"><span>$ ssh-add -L</span></span></code></pre></div><p>最後的命令將列出代表你的 PGP Auth 密鑰的 SSH（註釋應該會在結束的位置顯示： cardno:XXXXXXXX，表示它來自智能卡）。</p><p>為了啓用 ssh 的基於密鑰的登入，只需要在你要登入的遠程系統上添加 <code>ssh-add -L</code> 的輸出到 <code>~/.ssh/authorized_keys</code> 中。祝賀你，這將使你的 SSH 登入憑據更難以竊取。</p><p>此外，你可以從公共密鑰服務器上下載其它人的基於 PGP 的 ssh 公鑰，這樣就可以賦予他登入 ssh 的權利：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gpg --export-ssh-key [keyid]</span></span></code></pre></div><p>如果你有讓開發人員通過 ssh 來訪問 git 倉庫的需要，這將讓你非常方便。下一篇文章，我們將提供像保護你的密鑰那樣保護電子郵件帳户的小技巧。</p><hr>`,12)),s("p",null,[i[12]||(i[12]=a("via: ",-1)),t(e,{href:"https://www.linux.com/blog/learn/pgp/2018/3/protecting-code-integrity-pgp-part-6-using-pgp-git"},{default:l(()=>[...i[11]||(i[11]=[a("https://www.linux.com/blog/learn/pgp/2018/3/protecting-code-integrity-pgp-part-6-using-pgp-git",-1)])]),_:1})]),s("p",null,[i[16]||(i[16]=a("作者：",-1)),t(e,{href:"https://www.linux.com/users/mricon"},{default:l(()=>[...i[13]||(i[13]=[a("KONSTANTIN RYABITSEV",-1)])]),_:1}),i[17]||(i[17]=a(" 譯者：",-1)),t(e,{href:"https://github.com/qhwdw"},{default:l(()=>[...i[14]||(i[14]=[a("qhwdw",-1)])]),_:1}),i[18]||(i[18]=a(" 校對：",-1)),t(e,{href:"https://github.com/wxy"},{default:l(()=>[...i[15]||(i[15]=[a("wxy",-1)])]),_:1})]),s("p",null,[i[21]||(i[21]=a("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...i[19]||(i[19]=[a("LCTT",-1)])]),_:1}),i[22]||(i[22]=a(" 原創編譯，",-1)),t(e,{href:"https://linux.cn/"},{default:l(()=>[...i[20]||(i[20]=[a("Linux中國",-1)])]),_:1}),i[23]||(i[23]=a(" 榮譽推出",-1))])])}const x=p(d,[["render",o]]);export{y as __pageData,x as default};
